on('GET', `${A}/cash/stats`, async (req, res) => { const pm = transfers.filter((t) => ['pending_manual', 'pending_settlement'].includes(t.status)); const af = transfers.filter((t) => t.status === 'awaiting_funds'); const w = transfers.filter((t) => t.direction === 'withdraw'); const out = transfers.filter((t) => t.direction === 'wallet_to_bank'); const inn = transfers.filter((t) => t.direction === 'bank_to_wallet' && t.status === 'completed'); const col = transactions.filter((t) => t.status === 'authorized' && t.type === 'collect'); json(res, 200, { queues: { pendingManual: { count: pm.length, amount: sum(pm, 'net') }, awaitingFunds: { count: af.length, amount: sum(af) }, processing: { count: transfers.filter((t) => t.status === 'processing').length } }, today: { collected: { count: Math.round(col.length / 4), amount: Math.round(sum(col) / 4) }, withdrawn: { count: 3, amount: sum(w.slice(0, 3)) }, transfersOut: { count: 2, amount: sum(out.slice(0, 2)) }, transfersIn: { count: 1, amount: sum(inn.slice(0, 1)) } }, last7Days: { collected: { count: col.length, amount: sum(col) }, withdrawn: { count: w.length, amount: sum(w) }, transfersOut: { count: out.length, amount: sum(out) }, transfersIn: { count: inn.length, amount: sum(inn) } } }); });
on('GET', `${A}/cash/transfers`, async (req, res, q) => { let arr = transfers; if (q.get('status')) { const list = q.get('status').split(',').flatMap((s) => (s === 'pending_manual' ? ['pending_manual', 'pending_settlement'] : [s])); arr = arr.filter((t) => list.includes(t.status)); } if (q.get('direction')) arr = arr.filter((t) => t.direction === q.get('direction') || t.type === q.get('direction')); if (q.get('merchantId')) arr = arr.filter((t) => t.merchantId === q.get('merchantId')); if (q.get('q')) { const s = q.get('q').toLowerCase(); arr = arr.filter((t) => [t.reference, t.merchant, t.merchantEmail, t.bankReference].some((v) => String(v || '').toLowerCase().includes(s))); } const p = page(arr, q, 50); json(res, 200, { data: p.data, total: p.total, limit: p.limit, offset: p.offset }); });
on('GET', `${A}/cash/transfers/:id`, async (req, res, q, body, [id]) => { const t = transfers.find((x) => x.transferId === id); return t ? json(res, 200, t) : json(res, 404, { error: 'Transfert introuvable', code: 'TRANSFER_NOT_FOUND' }); });
const transition = (id, from, to, res, body, patch) => { const t = transfers.find((x) => x.transferId === id); if (!t) return json(res, 404, { error: 'Transfert introuvable', code: 'TRANSFER_NOT_FOUND' }); if (!from.includes(t.status)) return json(res, 409, { error: `Transfert non modifiable (statut ${t.status})`, code: 'INVALID_STATUS', status: t.status }); Object.assign(t, { status: to, completedAt: new Date().toISOString() }, patch); t.events.push({ at: new Date().toISOString(), type: to, by: `admin:${ADMIN_ID}`, ...body }); return json(res, 200, { success: true, ...t }); };
on('POST', `${A}/cash/transfers/:id/confirm-funds`, async (req, res, q, body, [id]) => (!body.amountReceived || !body.bankReference ? json(res, 422, { error: 'amountReceived et bankReference requis', code: 'VALIDATION_ERROR' }) : transition(id, ['awaiting_funds'], 'completed', res, { action: 'confirm_funds', bankReference: body.bankReference, amountReceived: body.amountReceived }, { bankReference: body.bankReference })));
on('POST', `${A}/cash/transfers/:id/mark-executed`, async (req, res, q, body, [id]) => (!body.bankReference ? json(res, 422, { error: 'bankReference requis', code: 'VALIDATION_ERROR' }) : transition(id, ['pending_manual', 'pending_settlement'], 'completed', res, { action: 'mark_executed', bankReference: body.bankReference }, { bankReference: body.bankReference })));
on('POST', `${A}/cash/transfers/:id/reject`, async (req, res, q, body, [id]) => (!body.reason ? json(res, 422, { error: 'reason requis', code: 'VALIDATION_ERROR' }) : transition(id, ['awaiting_funds', 'pending_manual', 'pending_settlement'], 'rejected', res, { action: 'reject', reason: body.reason }, { errorMessage: body.reason })));
