// ─── Statique (build CRA) ─────────────────────────────────────────
const MIME = { '.html': 'text/html; charset=utf-8', '.js': 'application/javascript', '.css': 'text/css', '.png': 'image/png', '.ico': 'image/x-icon', '.svg': 'image/svg+xml', '.json': 'application/json', '.woff2': 'font/woff2', '.map': 'application/json', '.txt': 'text/plain' };
const serveStatic = (req, res, pathname) => {
  if (!STATIC) return false;
  let file = path.join(STATIC, decodeURIComponent(pathname));
  if (!file.startsWith(STATIC)) return false;
  if (!fs.existsSync(file) || fs.statSync(file).isDirectory()) file = path.join(STATIC, 'index.html');
  if (!fs.existsSync(file)) return false;
  res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream' });
  fs.createReadStream(file).pipe(res);
  return true;
};

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const origin = req.headers.origin;
  if (origin) { res.setHeader('Access-Control-Allow-Origin', origin); res.setHeader('Access-Control-Allow-Credentials', 'true'); res.setHeader('Access-Control-Allow-Headers', 'Authorization, Content-Type'); res.setHeader('Access-Control-Allow-Methods', 'GET,POST,PUT,PATCH,DELETE,OPTIONS'); }
  if (req.method === 'OPTIONS') { res.writeHead(204); return res.end(); }
  for (const r of routes) {
    const m = r.method === req.method && url.pathname.match(r.re);
    if (m) {
      const body = ['POST', 'PUT', 'PATCH'].includes(req.method) ? await readBody(req) : {};
      if (url.pathname.startsWith('/api/') && !url.pathname.includes('/auth/') && !req.headers.authorization) return json(res, 401, { error: 'Jeton requis', code: 'UNAUTHENTICATED' });
      await new Promise((r2) => setTimeout(r2, 60 + Math.random() * 120)); // latence réaliste
      try { return await r.handler(req, res, url.searchParams, body, m.slice(1)); } catch (e) { return json(res, 500, { error: e.message }); }
    }
  }
  if (url.pathname.startsWith('/api/')) return json(res, 404, { error: `Route simulée absente : ${req.method} ${url.pathname}` });
  if (serveStatic(req, res, url.pathname)) return undefined;
  return json(res, 404, { error: 'Not found' });
});

server.listen(PORT, '127.0.0.1', () => {
  process.stdout.write(`C-Pay admin mock API : http://127.0.0.1:${PORT}  (rôle ${ROLE}, session ${SESSION ? 'active' : 'absente'}${STATIC ? `, statique ${STATIC}` : ''})\n`);
});
